import java.util.Arrays;
public class Solution {
    public int countPrimes(int n) {
        if (n <= 2) return 0;
        boolean[] isPrime = new boolean[n];
        Arrays.fill(isPrime, true);
        int cnt = 0;
        for (int p = 2; p * p < n; p++) {
            if (isPrime[p]) {
                for (int i = p * p; i < n; i += p) isPrime[i] = false;
            }
        }
        for (int i = 2; i < n; i++) if (isPrime[i]) cnt++;
        return cnt;
    }
}

