public class Solution {
    public static int[] findTwoElement(int[] arr) {
        long n = arr.length;
        long SN = n * (n + 1) / 2;
        long S2N = n * (n + 1) * (2 * n + 1) / 6;
        long S = 0, S2 = 0;
        for (int x : arr) {
            S += x;
            S2 += (long) x * x;
        }
        long val1 = S - SN; // x - y
        long val2 = S2 - S2N;
        val2 = val2 / val1; // x + y
        long x = (val1 + val2) / 2;
        long y = x - val1;
        return new int[]{(int) x, (int) y};
    }
}

public class Solution {
    public static long inversionCount(long[] arr) {
        return mergeSort(arr, 0, arr.length - 1);
    }

    private static long mergeSort(long[] arr, int low, int high) {
        long count = 0;
        if (low < high) {
            int mid = (low + high) / 2;
            count += mergeSort(arr, low, mid);
            count += mergeSort(arr, mid + 1, high);
            count += merge(arr, low, mid, high);
        }
        return count;
    }

    private static long merge(long[] arr, int low, int mid, int high) {
        long[] temp = new long[high - low + 1];
        int left = low, right = mid + 1, k = 0;
        long count = 0;
        while (left <= mid && right <= high) {
            if (arr[left] <= arr[right]) {
                temp[k++] = arr[left++];
            } else {
                temp[k++] = arr[right++];
                count += (mid - left + 1);
            }
        }
        while (left <= mid) temp[k++] = arr[left++];
        while (right <= high) temp[k++] = arr[right++];
        System.arraycopy(temp, 0, arr, low, temp.length);
        return count;
    }
}

