            sum += num;
            if (map.containsKey(sum - k)) {
                count += map.get(sum - k);
            }
            map.put(sum, map.getOrDefault(sum, 0) + 1);
        }
        return count;
    }
}

public class Solution {
    public static int solve(int[] A, int B) {
        int count = 0;
        for (int i = 0; i < A.length; i++) {
            int xor = 0;
            for (int j = i; j < A.length; j++) {
                xor ^= A[j];
                if (xor == B) count++;
            }
        }
        return count;
    }
}

