public class Solution {
    public static int solve(int[] A, int B) {
        HashMap<Integer, Integer> map = new HashMap<>();
        int xr = 0, count = 0;
        map.put(0, 1);
        for (int x : A) {
            xr ^= x;
            int target = xr ^ B;
            if (map.containsKey(target)) {
                count += map.get(target);
            }
            map.put(xr, map.getOrDefault(xr, 0) + 1);
        }
        return count;
    }
}

