        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (nums[mid] > nums[mid - 1] && nums[mid] > nums[mid + 1]) return mid;
            if (nums[mid] > nums[mid - 1]) low = mid + 1;
            else high = mid - 1;
        }
        return -1;
    }
}

public class Solution {
    public static double findMedianSortedArrays(int[] nums1, int[] nums2) {
        int n1 = nums1.length, n2 = nums2.length;
        int[] arr = new int[n1 + n2];
        int i = 0, j = 0, k = 0;
        while (i < n1 && j < n2) {
            if (nums1[i] <= nums2[j]) arr[k++] = nums1[i++];
            else arr[k++] = nums2[j++];
        }
        while (i < n1) arr[k++] = nums1[i++];
        while (j < n2) arr[k++] = nums2[j++];
        int n = n1 + n2;
        if (n % 2 == 1) return arr[n / 2];
        return ((double) arr[n / 2] + arr[n / 2 - 1]) / 2.0;
    }
}

public class Solution {
    public static double findMedianSortedArrays(int[] nums1, int[] nums2) {
        int n1 = nums1.length, n2 = nums2.length;
        if (n1 > n2) return findMedianSortedArrays(nums2, nums1);
        int low = 0, high = n1, left = (n1 + n2 + 1) / 2;
        int n = n1 + n2;
        while (low <= high) {
            int mid1 = (low + high) / 2;
            int mid2 = left - mid1;
            int l1 = mid1 > 0 ? nums1[mid1 - 1] : Integer.MIN_VALUE;
            int l2 = mid2 > 0 ? nums2[mid2 - 1] : Integer.MIN_VALUE;
            int r1 = mid1 < n1 ? nums1[mid1] : Integer.MAX_VALUE;
            int r2 = mid2 < n2 ? nums2[mid2] : Integer.MAX_VALUE;

            if (l1 <= r2 && l2 <= r1) {
                if (n % 2 == 1) return Math.max(l1, l2);
                return ((double) Math.max(l1, l2) + Math.min(r1, r2)) / 2.0;
            } else if (l1 > r2) {
                high = mid1 - 1;
            } else {
                low = mid1 + 1;
            }
        }
        return 0.0;
    }
}

public class Solution {
    public static long kthElement(int[] arr1, int[] arr2, int n, int m, int k) {
        int i = 0, j = 0, count = 0;
        while (i < n && j < m) {
            if (arr1[i] <= arr2[j]) {
                if (++count == k) return arr1[i];
                i++;
            } else {
                if (++count == k) return arr2[j];
                j++;
            }
        }
        while (i < n) {
            if (++count == k) return arr1[i];
            i++;
        }
        while (j < m) {
            if (++count == k) return arr2[j];
            j++;
        }
        return -1;
    }
}

public class Solution {
    public static long kthElement(int[] arr1, int[] arr2, int n, int m, int k) {
        if (n > m) return kthElement(arr2, arr1, m, n, k);
        int low = Math.max(0, k - m), high = Math.min(k, n);
        while (low <= high) {
            int cut1 = (low + high) / 2;
            int cut2 = k - cut1;
            int l1 = cut1 == 0 ? Integer.MIN_VALUE : arr1[cut1 - 1];
            int l2 = cut2 == 0 ? Integer.MIN_VALUE : arr2[cut2 - 1];
            int r1 = cut1 == n ? Integer.MAX_VALUE : arr1[cut1];
            int r2 = cut2 == m ? Integer.MAX_VALUE : arr2[cut2];

            if (l1 <= r2 && l2 <= r1) {
                return Math.max(l1, l2);
            } else if (l1 > r2) {
                high = cut1 - 1;
            } else {
                low = cut1 + 1;
            }
        }
        return -1;
    }
}

public class Solution {
    public static double findSmallestMaxDist(int[] stations, int K) {
        int n = stations.length;
        int[] howMany = new int[n - 1];
        for (int gas = 1; gas <= K; gas++) {
            double maxSection = -1;
            int maxIdx = -1;
            for (int i = 0; i < n - 1; i++) {
                double diff = stations[i + 1] - stations[i];
                double sectionLen = diff / (double) (howMany[i] + 1);
                if (sectionLen > maxSection) {
                    maxSection = sectionLen;
                    maxIdx = i;
                }
            }
            howMany[maxIdx]++;
        }
        double maxAns = -1;
        for (int i = 0; i < n - 1; i++) {
            double diff = stations[i + 1] - stations[i];
            maxAns = Math.max(maxAns, diff / (double) (howMany[i] + 1));
        }
        return maxAns;
    }
}

public class Solution {
    public static Node deleteTail(Node head) {
        if (head == null || head.next == null) return null;
        Node curr = head;
        while (curr.next.next != null) curr = curr.next;
        curr.next = null;
        return head;
    }
}

public class Solution {
    public static double findSmallestMaxDist(int[] stations, int K) {
        int n = stations.length;
        double low = 0, high = 0;
        for (int i = 0; i < n - 1; i++) high = Math.max(high, stations[i + 1] - stations[i]);
        double diff = 1e-6;
        while (high - low > diff) {
            double mid = (low + high) / 2.0;
            if (countStations(stations, mid) <= K) high = mid;
            else low = mid;
        }
        return high;
    }

    private static int countStations(int[] stations, double dist) {
        int count = 0;
        for (int i = 1; i < stations.length; i++) {
            int numInBetween = (int) ((stations[i] - stations[i - 1]) / dist);
            if ((stations[i] - stations[i - 1]) == numInBetween * dist) numInBetween--;
            count += numInBetween;
        }
        return count;
    }
}

public class Solution {
    public static int splitArray(int[] nums, int k) {
        int low = 0, high = 0;
        for (int x : nums) { low = Math.max(low, x); high += x; }
        int ans = high;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (canSplit(nums, mid, k)) {
                ans = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        return ans;
    }

    private static boolean canSplit(int[] nums, int maxSum, int k) {
        int pieces = 1, current = 0;
        for (int x : nums) {
            if (current + x <= maxSum) current += x;
            else { pieces++; current = x; }
        }
        return pieces <= k;
    }
}

