public class Solution {
    public static int rowWithMax1s(int[][] arr, int n, int m) {
        int maxCount = 0, maxRow = -1;
        for (int i = 0; i < n; i++) {
            int count = 0;
            for (int j = 0; j < m; j++) {
                if (arr[i][j] == 1) count++;
            }
            if (count > maxCount) {
                maxCount = count;
                maxRow = i;
            }
        }
        return maxRow;
    }
