public class Solution {
    public static int countSubsequences(int[] arr, int k) {
        int[] dp = new int[k + 1];
        dp[0] = 1;
        for (int num : arr) {
            for (int j = k; j >= num; j--) {
                dp[j] = (dp[j] + dp[j - num]) % 1_000_000_007;
            }
        }
        return dp[k];
    }
}

