        Stack<Integer> st = new Stack<>();
        Node curr = head;
        while (curr != null) { st.push(curr.data); curr = curr.next; }
        curr = head;
        while (curr != null) { curr.data = st.pop(); curr = curr.next; }
        return head;
    }
