        if (head == null) return ans;
        Node left = head, right = head;
        while (right.next != null) right = right.next;
        while (left != null && right != null && left.data < right.data) {
            int sum = left.data + right.data;
            if (sum == target) {
                ArrayList<Integer> pair = new ArrayList<>();
                pair.add(left.data);
                pair.add(right.data);
                ans.add(pair);
                left = left.next;
                right = right.prev;
