public class Solution {
    public static int findXOR(int l, int r) {
        return xorTill(r) ^ xorTill(l - 1);
    }

    private static int xorTill(int n) {
        if (n % 4 == 1) return 1;
        if (n % 4 == 2) return n + 1;
        if (n % 4 == 3) return 0;
        return n;
    }
}

