public class Solution {
    public static int findPlatform(int[] arr, int[] dep, int n) {
        int maxPlat = 1;
        for (int i = 0; i < n; i++) {
            int plat = 1;
            for (int j = 0; j < n; j++) {
                if (i != j && arr[i] >= arr[j] && dep[j] >= arr[i]) plat++;
            }
            maxPlat = Math.max(maxPlat, plat);
        }
        return maxPlat;
    }
}

