public class Solution {
    public static String minWindow(String s, String t) {
        if (s.length() < t.length()) return "";
        Map<Character, Integer> tMap = new HashMap<>();
        for (char c : t.toCharArray()) tMap.put(c, tMap.getOrDefault(c, 0) + 1);

        String minStr = "";
        int minLen = Integer.MAX_VALUE;
        for (int i = 0; i < s.length(); i++) {
            Map<Character, Integer> sMap = new HashMap<>();
            for (int j = i; j < s.length(); j++) {
                sMap.put(s.charAt(j), sMap.getOrDefault(s.charAt(j), 0) + 1);
                boolean containsAll = true;
                for (char key : tMap.keySet()) {
                    if (sMap.getOrDefault(key, 0) < tMap.get(key)) {
                        containsAll = false;
                        break;
                    }
                }
                if (containsAll && (j - i + 1) < minLen) {
                    minLen = j - i + 1;
                    minStr = s.substring(i, j + 1);
                    break;
                }
            }
        }
        return minStr;
    }
}

public class Solution {
    public static String minWindow(String s, String t) {
        int[] map = new int[128];
        for (char c : t.toCharArray()) map[c]++;
        int count = t.length(), left = 0, minLen = Integer.MAX_VALUE, start = 0;
        for (int right = 0; right < s.length(); right++) {
            if (map[s.charAt(right)]-- > 0) count--;
            while (count == 0) {
                if (right - left + 1 < minLen) {
                    minLen = right - left + 1;
                    start = left;
                }
                if (++map[s.charAt(left++)] > 0) count++;
            }
        }
        return minLen == Integer.MAX_VALUE ? "" : s.substring(start, start + minLen);
    }
}

public class Solution {
    public static String minWindow(String s1, String s2) {
        String ans = "";
        int minLen = Integer.MAX_VALUE;
        int m = s1.length(), n = s2.length();
        int j = 0;
        for (int i = 0; i < m; i++) {
            if (s1.charAt(i) == s2.charAt(j)) {
                j++;
                if (j == n) {
                    int end = i + 1;
                    j--;
                    while (j >= 0) {
                        if (s1.charAt(i) == s2.charAt(j)) j--;
                        i--;
                    }
                    i++;
                    j++;
                    if (end - i < minLen) {
                        minLen = end - i;
                        ans = s1.substring(i, end);
                    }
                }
            }
        }
        return ans;
    }
}

