public class Solution {
    static class MinStack {
        Stack<Long> stack = new Stack<>();
        Long min;

        public void push(int val) {
            Long x = (long) val;
            if (stack.isEmpty()) {
                stack.push(x);
                min = x;
            } else if (x < min) {
                stack.push(2 * x - min);
                min = x;
            } else {
                stack.push(x);
            }
        }

        public void pop() {
            if (stack.isEmpty()) return;
            Long x = stack.pop();
            if (x < min) min = 2 * min - x;
        }

        public int top() {
            Long x = stack.peek();
            if (x < min) return min.intValue();
            return x.intValue();
        }

        public int getMin() { return min.intValue(); }
    }
}

public class Solution {
