public class Solution {
    static class LFUCache {
        int cap, minFreq;
        Map<Integer, Integer> vals = new HashMap<>();
        Map<Integer, Integer> counts = new HashMap<>();
        Map<Integer, LinkedHashSet<Integer>> lists = new HashMap<>();

        public LFUCache(int capacity) {
            cap = capacity;
            minFreq = -1;
            lists.put(1, new LinkedHashSet<>());
        }

        public int get(int key) {
            if (!vals.containsKey(key)) return -1;
            int count = counts.get(key);
            counts.put(key, count + 1);
            lists.get(count).remove(key);
            if (count == minFreq && lists.get(count).isEmpty()) minFreq++;
            if (!lists.containsKey(count + 1)) lists.put(count + 1, new LinkedHashSet<>());
            lists.get(count + 1).add(key);
            return vals.get(key);
        }

        public void put(int key, int value) {
            if (cap <= 0) return;
            if (vals.containsKey(key)) {
                vals.put(key, value);
                get(key);
                return;
            }
            if (vals.size() >= cap) {
                int evict = lists.get(minFreq).iterator().next();
                lists.get(minFreq).remove(evict);
                vals.remove(evict);
                counts.remove(evict);
            }
            vals.put(key, value);
            counts.put(key, 1);
            minFreq = 1;
            lists.get(1).add(key);
        }
    }
}

