public class Solution {
    public static void allTraversals(TreeNode root) {
        List<Integer> pre = new ArrayList<>(), in = new ArrayList<>(), post = new ArrayList<>();
        if (root == null) return;
        Stack<Pair> st = new Stack<>();
        st.push(new Pair(root, 1));
        while (!st.isEmpty()) {
            Pair it = st.pop();
            if (it.num == 1) {
                pre.add(it.node.val);
                it.num++;
                st.push(it);
                if (it.node.left != null) st.push(new Pair(it.node.left, 1));
            } else if (it.num == 2) {
                in.add(it.node.val);
                it.num++;
                st.push(it);
                if (it.node.right != null) st.push(new Pair(it.node.right, 1));
            } else {
                post.add(it.node.val);
            }
        }
    }
}

