import java.util.ArrayList;

public class Solution {
    public static ArrayList<Integer> boundary(TreeNode node) {
        ArrayList<Integer> ans = new ArrayList<>();
        if (node == null) return ans;
        if (!isLeaf(node)) ans.add(node.val);
        addLeftBoundary(node, ans);
        addLeaves(node, ans);
        addRightBoundary(node, ans);
        return ans;
    }

    private static boolean isLeaf(TreeNode node) {
        return node.left == null && node.right == null;
    }

    private static void addLeftBoundary(TreeNode root, ArrayList<Integer> res) {
        TreeNode curr = root.left;
        while (curr != null) {
            if (!isLeaf(curr)) res.add(curr.val);
            if (curr.left != null) curr = curr.left;
            else curr = curr.right;
        }
    }

    private static void addRightBoundary(TreeNode root, ArrayList<Integer> res) {
        TreeNode curr = root.right;
        ArrayList<Integer> tmp = new ArrayList<>();
        while (curr != null) {
            if (!isLeaf(curr)) tmp.add(curr.val);
            if (curr.right != null) curr = curr.right;
            else curr = curr.left;
        }
        for (int i = tmp.size() - 1; i >= 0; --i) res.add(tmp.get(i));
    }

    private static void addLeaves(TreeNode root, ArrayList<Integer> res) {
        if (isLeaf(root)) { res.add(root.val); return; }
        if (root.left != null) addLeaves(root.left, res);
        if (root.right != null) addLeaves(root.right, res);
    }
}

