class Tuple {
    TreeNode node;
    int row, col;
    Tuple(TreeNode n, int r, int c) { node = n; row = r; col = c; }
}

public class Solution {
    public static List<List<Integer>> verticalTraversal(TreeNode root) {
        TreeMap<Integer, TreeMap<Integer, PriorityQueue<Integer>>> map = new TreeMap<>();
        Queue<Tuple> q = new LinkedList<>();
        q.offer(new Tuple(root, 0, 0));
        while (!q.isEmpty()) {
            Tuple tuple = q.poll();
            TreeNode node = tuple.node;
            int x = tuple.row, y = tuple.col;
            map.computeIfAbsent(x, k -> new TreeMap<>()).computeIfAbsent(y, k -> new PriorityQueue<>()).offer(node.val);
            if (node.left != null) q.offer(new Tuple(node.left, x - 1, y + 1));
            if (node.right != null) q.offer(new Tuple(node.right, x + 1, y + 1));
        }
        List<List<Integer>> list = new ArrayList<>();
        for (TreeMap<Integer, PriorityQueue<Integer>> ys : map.values()) {
            list.add(new ArrayList<>());
            for (PriorityQueue<Integer> nodes : ys.values()) {
                while (!nodes.isEmpty()) list.get(list.size() - 1).add(nodes.poll());
            }
        }
        return list;
    }
}

