class PairNode {
    TreeNode node;
    int num;
    PairNode(TreeNode n, int num) { this.node = n; this.num = num; }
}

public class Solution {
    public static int widthOfBinaryTree(TreeNode root) {
        if (root == null) return 0;
        int ans = 0;
        Queue<PairNode> q = new LinkedList<>();
        q.offer(new PairNode(root, 0));
        while (!q.isEmpty()) {
            int size = q.size();
            int mmin = q.peek().num;
            int first = 0, last = 0;
            for (int i = 0; i < size; i++) {
                int cur_id = q.peek().num - mmin;
                TreeNode node = q.peek().node;
                q.poll();
                if (i == 0) first = cur_id;
                if (i == size - 1) last = cur_id;
                if (node.left != null) q.offer(new PairNode(node.left, cur_id * 2 + 1));
                if (node.right != null) q.offer(new PairNode(node.right, cur_id * 2 + 2));
            }
            ans = Math.max(ans, last - first + 1);
        }
        return ans;
    }
}

import java.util.Stack;

public class Solution {
    public static void flatten(TreeNode root) {
        if (root == null) return;
        Stack<TreeNode> st = new Stack<>();
        st.push(root);
        while (!st.isEmpty()) {
            TreeNode curr = st.pop();
            if (curr.right != null) st.push(curr.right);
            if (curr.left != null) st.push(curr.left);
            if (!st.isEmpty()) curr.right = st.peek();
            curr.left = null;
        }
    }
}

