public class Solution {
    public static List<Integer> distanceK(TreeNode root, TreeNode target, int k) {
        Map<TreeNode, TreeNode> parent_track = new HashMap<>();
        markParents(root, parent_track);
        Map<TreeNode, Boolean> visited = new HashMap<>();
        Queue<TreeNode> queue = new LinkedList<>();
        queue.offer(target);
        visited.put(target, true);
        int curr_level = 0;
        while (!queue.isEmpty()) {
            int size = queue.size();
            if (curr_level == k) break;
            curr_level++;
            for (int i = 0; i < size; i++) {
                TreeNode current = queue.poll();
                if (current.left != null && visited.get(current.left) == null) {
                    visited.put(current.left, true);
                    queue.offer(current.left);
                }
                if (current.right != null && visited.get(current.right) == null) {
                    visited.put(current.right, true);
                    queue.offer(current.right);
                }
                if (parent_track.get(current) != null && visited.get(parent_track.get(current)) == null) {
                    visited.put(parent_track.get(current), true);
                    queue.offer(parent_track.get(current));
                }
            }
        }
        List<Integer> result = new ArrayList<>();
        while (!queue.isEmpty()) result.add(queue.poll().val);
        return result;
    }

    private static void markParents(TreeNode root, Map<TreeNode, TreeNode> parent_track) {
        Queue<TreeNode> queue = new LinkedList<>();
        queue.offer(root);
        while (!queue.isEmpty()) {
            TreeNode current = queue.poll();
            if (current.left != null) { parent_track.put(current.left, current); queue.offer(current.left); }
            if (current.right != null) { parent_track.put(current.right, current); queue.offer(current.right); }
        }
    }
}

