public class Solution {
    public static TreeNode buildTree(int[] inorder, int[] postorder) {
        if (inorder == null || postorder == null || inorder.length != postorder.length) return null;
        HashMap<Integer, Integer> hm = new HashMap<>();
        for (int i = 0; i < inorder.length; ++i) hm.put(inorder[i], i);
        return build(inorder, 0, inorder.length - 1, postorder, 0, postorder.length - 1, hm);
    }

    private static TreeNode build(int[] in, int is, int ie, int[] post, int ps, int pe, HashMap<Integer, Integer> hm) {
        if (ps > pe || is > ie) return null;
        TreeNode root = new TreeNode(post[pe]);
        int ri = hm.get(post[pe]);
        TreeNode leftchild = build(in, is, ri - 1, post, ps, ps + ri - is - 1, hm);
        TreeNode rightchild = build(in, ri + 1, ie, post, ps + ri - is, pe - 1, hm);
        root.left = leftchild;
        root.right = rightchild;
        return root;
    }
}

