public class Solution {
    public static TreeNode lowestCommonAncestor(TreeNode root, TreeNode p, TreeNode q) {
        if (root == null) return null;
        int cur = root.val;
        if (cur < p.val && cur < q.val) return lowestCommonAncestor(root.right, p, q);
        if (cur > p.val && cur > q.val) return lowestCommonAncestor(root.left, p, q);
        return root;
    }
}

public class Solution {
    public static TreeNode lowestCommonAncestor(TreeNode root, TreeNode p, TreeNode q) {
        while (root != null) {
            int cur = root.val;
            if (cur < p.val && cur < q.val) root = root.right;
            else if (cur > p.val && cur > q.val) root = root.left;
            else return root;
        }
        return null;
    }
}

public class Solution {
    public static TreeNode bstFromPreorder(int[] preorder) {
        return bst(preorder, Integer.MAX_VALUE, new int[]{0});
    }

    private static TreeNode bst(int[] A, int bound, int[] i) {
        if (i[0] == A.length || A[i[0]] > bound) return null;
        TreeNode root = new TreeNode(A[i[0]++]);
        root.left = bst(A, root.val, i);
        root.right = bst(A, bound, i);
        return root;
    }
}

