public class Solution {
    // Binary Heap representation in an Array:
    // Left Child: 2*i + 1, Right Child: 2*i + 2, Parent: (i - 1) / 2
    public static int getParent(int i) { return (i - 1) / 2; }
    public static int getLeftChild(int i) { return 2 * i + 1; }
    public static int getRightChild(int i) { return 2 * i + 2; }
}

