public class Solution {
    public static void heapify(int[] arr, int n, int i) {
        int largest = i;
        int left = 2 * i + 1;
        int right = 2 * i + 2;
        if (left < n && arr[left] > arr[largest]) largest = left;
        if (right < n && arr[right] > arr[largest]) largest = right;
        if (largest != i) {
            int swap = arr[i];
            arr[i] = arr[largest];
            arr[largest] = swap;
            heapify(arr, n, largest);
        }
    }
}

public class Solution {
    public static int minSubsetSumDifference(int[] arr, int n) {
        int totSum = 0;
        for (int x : arr) totSum += x;
        return solve(n - 1, 0, totSum, arr);
    }
    private static int solve(int ind, int curSum, int totSum, int[] arr) {
        if (ind < 0) return Math.abs((totSum - curSum) - curSum);
        return Math.min(solve(ind - 1, curSum + arr[ind], totSum, arr), solve(ind - 1, curSum, totSum, arr));
    }
}

public class Solution {
    public static void heapify(int[] arr, int n, int i) {
        while (true) {
            int largest = i;
            int left = 2 * i + 1;
            int right = 2 * i + 2;
            if (left < n && arr[left] > arr[largest]) largest = left;
            if (right < n && arr[right] > arr[largest]) largest = right;
            if (largest == i) break;
            int swap = arr[i];
            arr[i] = arr[largest];
            arr[largest] = swap;
            i = largest;
        }
    }
}

public class Solution {
    public static void buildHeap(int[] arr, int n) {
        for (int i = n / 2 - 1; i >= 0; i--) {
            heapify(arr, n, i);
        }
    }

    private static void heapify(int[] arr, int n, int i) {
        int largest = i, l = 2 * i + 1, r = 2 * i + 2;
        if (l < n && arr[l] > arr[largest]) largest = l;
        if (r < n && arr[r] > arr[largest]) largest = r;
        if (largest != i) {
            int swap = arr[i];
            arr[i] = arr[largest];
            arr[largest] = swap;
            heapify(arr, n, largest);
        }
    }
}

