public class Solution {
    static class MaxHeap {
        int[] arr = new int[1000];
        int size = 0;

        void push(int val) {
            int i = size++;
            arr[i] = val;
            while (i != 0 && arr[(i - 1) / 2] < arr[i]) {
                int temp = arr[i];
                arr[i] = arr[(i - 1) / 2];
                arr[(i - 1) / 2] = temp;
                i = (i - 1) / 2;
            }
        }

        int pop() {
            if (size <= 0) return -1;
            if (size == 1) return arr[--size];
            int root = arr[0];
            arr[0] = arr[--size];
            heapify(0);
            return root;
        }

        void heapify(int i) {
            int l = 2 * i + 1, r = 2 * i + 2, largest = i;
            if (l < size && arr[l] > arr[largest]) largest = l;
            if (r < size && arr[r] > arr[largest]) largest = r;
            if (largest != i) {
                int temp = arr[i];
                arr[i] = arr[largest];
                arr[largest] = temp;
                heapify(largest);
            }
        }
    }
}

import java.util.PriorityQueue;

public class Solution {
    public static void nearlySorted(int[] arr, int num, int k) {
        PriorityQueue<Integer> pq = new PriorityQueue<>();
        int index = 0;
        for (int i = 0; i <= Math.min(num - 1, k); i++) pq.add(arr[i]);
        for (int i = k + 1; i < num; i++) {
            arr[index++] = pq.poll();
            pq.add(arr[i]);
        }
        while (!pq.isEmpty()) arr[index++] = pq.poll();
    }
}

