        }

        int pop() {
            if (size <= 0) return -1;
            if (size == 1) return arr[--size];
            int root = arr[0];
            arr[0] = arr[--size];
            heapify(0);
            return root;
        }

        void heapify(int i) {
            int l = 2 * i + 1, r = 2 * i + 2, largest = i;
            if (l < size && arr[l] > arr[largest]) largest = l;
            if (r < size && arr[r] > arr[largest]) largest = r;
            if (largest != i) {
                int temp = arr[i];
                arr[i] = arr[largest];
                arr[largest] = temp;
                heapify(largest);
            }
        }
    }
}

