public class Solution {
    static class Twitter {
        private static int timeStamp = 0;
        private Map<Integer, User> userMap = new HashMap<>();

        class Tweet {
            int id, time;
            Tweet next;
            Tweet(int id) { this.id = id; time = timeStamp++; next = null; }
        }

        class User {
            int id;
            Set<Integer> followed = new HashSet<>();
            Tweet tweet_head;
            User(int id) { this.id = id; follow(id); tweet_head = null; }
            void follow(int id) { followed.add(id); }
            void unfollow(int id) { followed.remove(id); }
            void post(int id) { Tweet t = new Tweet(id); t.next = tweet_head; tweet_head = t; }
        }

        public void postTweet(int userId, int tweetId) {
            userMap.computeIfAbsent(userId, User::new).post(tweetId);
        }

        public List<Integer> getNewsFeed(int userId) {
            List<Integer> res = new ArrayList<>();
            if (!userMap.containsKey(userId)) return res;
            Set<Integer> users = userMap.get(userId).followed;
            PriorityQueue<Tweet> q = new PriorityQueue<>(users.size(), (a, b) -> b.time - a.time);
            for (int u : users) {
                Tweet t = userMap.get(u).tweet_head;
                if (t != null) q.add(t);
            }
            int n = 0;
            while (!q.isEmpty() && n < 10) {
                Tweet t = q.poll();
                res.add(t.id);
                n++;
                if (t.next != null) q.add(t.next);
            }
            return res;
        }

        public void follow(int followerId, int followeeId) {
            userMap.computeIfAbsent(followerId, User::new).follow(followeeId);
            userMap.computeIfAbsent(followeeId, User::new);
        }

        public void unfollow(int followerId, int followeeId) {
            if (userMap.containsKey(followerId) && followerId != followeeId) {
                userMap.get(followerId).unfollow(followeeId);
            }
        }
    }
}

