public class Solution {
    public static List<Integer> maxCombinations(int N, int K, int[] A, int[] B) {
        Arrays.sort(A);
        Arrays.sort(B);
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> b[0] - a[0]);
        Set<String> set = new HashSet<>();
        pq.add(new int[]{A[N - 1] + B[N - 1], N - 1, N - 1});
        set.add((N - 1) + "," + (N - 1));

        List<Integer> res = new ArrayList<>();
        while (K-- > 0 && !pq.isEmpty()) {
            int[] top = pq.poll();
            res.add(top[0]);
            int i = top[1], j = top[2];

            if (i - 1 >= 0 && !set.contains((i - 1) + "," + j)) {
                pq.add(new int[]{A[i - 1] + B[j], i - 1, j});
                set.add((i - 1) + "," + j);
            }
            if (j - 1 >= 0 && !set.contains(i + "," + (j - 1))) {
                pq.add(new int[]{A[i] + B[j - 1], i, j - 1});
                set.add(i + "," + (j - 1));
            }
        }
        return res;
    }
}

