public class Solution {
    public static boolean isBipartite(int[][] graph) {
        int n = graph.length;
        int[] color = new int[n];
        Arrays.fill(color, -1);
        for (int i = 0; i < n; i++) {
            if (color[i] == -1 && !check(i, graph, color)) return false;
        }
        return true;
    }

    private static boolean check(int start, int[][] graph, int[] color) {
        Queue<Integer> q = new LinkedList<>();
        q.add(start);
        color[start] = 0;
        while (!q.isEmpty()) {
            int node = q.poll();
            for (int it : graph[node]) {
                if (color[it] == -1) {
                    color[it] = 1 - color[node];
                    q.add(it);
                } else if (color[it] == color[node]) return false;
            }
        }
        return true;
    }
}

public class Solution {
    public int maxProfit(int[] prices) {
        int n = prices.length;
        if (n <= 1) return 0;
        int buy = -prices[0], sell = 0, rest = 0;
        for (int i = 1; i < n; i++) {
            int prevSell = sell;
            sell = buy + prices[i];
            buy = Math.max(buy, rest - prices[i]);
            rest = Math.max(rest, prevSell);
        }
        return Math.max(sell, rest);
    }
}

