public class Solution {
    public static int[] shortestPath(int N, int M, int[][] edges) {
        List<List<int[]>> adj = new ArrayList<>();
        for (int i = 0; i < N; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) adj.get(e[0]).add(new int[]{e[1], e[2]});
        int[] dist = new int[N];
        Arrays.fill(dist, (int) 1e9);
        dist[0] = 0;
        // Topo Sort DFS
        boolean[] vis = new boolean[N];
        Stack<Integer> st = new Stack<>();
        for (int i = 0; i < N; i++) if (!vis[i]) topo(i, adj, vis, st);
        while (!st.isEmpty()) {
            int node = st.pop();
            if (dist[node] != 1e9) {
                for (int[] it : adj.get(node)) {
                    int v = it[0], wt = it[1];
                    if (dist[node] + wt < dist[v]) dist[v] = dist[node] + wt;
                }
            }
        }
        for (int i = 0; i < N; i++) if (dist[i] == 1e9) dist[i] = -1;
        return dist;
    }

    private static void topo(int node, List<List<int[]>> adj, boolean[] vis, Stack<Integer> st) {
        vis[node] = true;
        for (int[] it : adj.get(node)) if (!vis[it[0]]) topo(it[0], adj, vis, st);
        st.push(node);
    }
}

