public class Solution {
    public int findTargetSumWays(int[] nums, int target) {
        int totSum = 0;
        for (int x : nums) totSum += x;
        if (totSum - target < 0 || (totSum - target) % 2 != 0) return 0;
        int s2 = (totSum - target) / 2;
        int[] dp = new int[s2 + 1];
        dp[0] = 1;
        for (int val : nums) {
            for (int t = s2; t >= val; t--) {
                dp[t] += dp[t - val];
            }
        }
        return dp[s2];
    }
}

