public class Solution {
    public static int shortestDistance(int[][] grid, int[] source, int[] destination) {
        if (source[0] == destination[0] && source[1] == destination[1]) return 0;
        int n = grid.length, m = grid[0].length;
        int[][] dist = new int[n][m];
        for (int[] r : dist) Arrays.fill(r, (int) 1e9);
        dist[source[0]][source[1]] = 0;
        Queue<int[]> q = new LinkedList<>();
        q.add(new int[]{0, source[0], source[1]});
        int[] dr = {-1, 0, 1, 0}, dc = {0, 1, 0, -1};
        while (!q.isEmpty()) {
            int[] it = q.poll();
            int dis = it[0], r = it[1], c = it[2];
            for (int i = 0; i < 4; i++) {
                int nr = r + dr[i], nc = c + dc[i];
                if (nr >= 0 && nr < n && nc >= 0 && nc < m && grid[nr][nc] == 1 && dis + 1 < dist[nr][nc]) {
                    dist[nr][nc] = 1 + dis;
                    if (nr == destination[0] && nc == destination[1]) return dis + 1;
                    q.add(new int[]{1 + dis, nr, nc});
                }
            }
        }
        return -1;
    }
}

