public class Solution {
    public static List<Integer> shortestPath(int n, int m, int edges[][]) {
        List<List<int[]>> adj = new ArrayList<>();
        for (int i = 0; i <= n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) {
            adj.get(e[0]).add(new int[]{e[1], e[2]});
            adj.get(e[1]).add(new int[]{e[0], e[2]});
        }
        int[] dist = new int[n + 1], parent = new int[n + 1];
        Arrays.fill(dist, (int) 1e9);
        for (int i = 1; i <= n; i++) parent[i] = i;
        dist[1] = 0;
        PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));
        pq.add(new int[]{0, 1});
        while (!pq.isEmpty()) {
            int[] it = pq.poll();
            int d = it[0], node = it[1];
            for (int[] next : adj.get(node)) {
                int adjNode = next[0], edW = next[1];
                if (d + edW < dist[adjNode]) {
                    dist[adjNode] = d + edW;
                    parent[adjNode] = node;
                    pq.add(new int[]{dist[adjNode], adjNode});
                }
            }
        }
        List<Integer> path = new ArrayList<>();
        if (dist[n] == 1e9) { path.add(-1); return path; }
        int curr = n;
        while (parent[curr] != curr) { path.add(curr); curr = parent[curr]; }
        path.add(1);
        Collections.reverse(path);
        return path;
    }
}

