public class Solution {
    public static int minimumMultiplications(int[] arr, int start, int end) {
        if (start == end) return 0;
        Queue<int[]> q = new LinkedList<>();
        q.add(new int[]{start, 0});
        int[] dist = new int[100000];
        Arrays.fill(dist, (int) 1e9);
        dist[start] = 0;
        int mod = 100000;
        while (!q.isEmpty()) {
            int[] it = q.poll();
            int node = it[0], steps = it[1];
            for (int num : arr) {
                int next = (node * num) % mod;
                if (steps + 1 < dist[next]) {
                    dist[next] = steps + 1;
                    if (next == end) return steps + 1;
                    q.add(new int[]{next, steps + 1});
                }
            }
        }
        return -1;
    }
}

public class Solution {
    static class DisjointSet {
        int[] parent, size;
        DisjointSet(int n) {
            parent = new int[n + 1];
            size = new int[n + 1];
            for (int i = 0; i <= n; i++) { parent[i] = i; size[i] = 1; }
        }
        int findUPar(int node) {
            if (node == parent[node]) return node;
            return parent[node] = findUPar(parent[node]);
        }
        void unionBySize(int u, int v) {
            int ulp_u = findUPar(u), ulp_v = findUPar(v);
            if (ulp_u == ulp_v) return;
            if (size[ulp_u] < size[ulp_v]) { parent[ulp_u] = ulp_v; size[ulp_v] += size[ulp_u]; }
            else { parent[ulp_v] = ulp_u; size[ulp_u] += size[ulp_v]; }
        }
    }
}

