                low[node] = Math.min(low[node], low[it]);
                if (low[it] > tin[node]) bridges.add(Arrays.asList(node, it));
            } else {
                low[node] = Math.min(low[node], tin[it]);
            }
        }
    }
}

public class Solution {
    public static int ninjaTraining(int n, int points[][]) {
        return solve(n - 1, 3, points);
    }
    private static int solve(int day, int last, int[][] points) {
        if (day == 0) {
            int maxi = 0;
            for (int i = 0; i <= 2; i++) {
                if (i != last) maxi = Math.max(maxi, points[0][i]);
            }
            return maxi;
        }
        int maxi = 0;
        for (int i = 0; i <= 2; i++) {
            if (i != last) {
                int point = points[day][i] + solve(day - 1, i, points);
                maxi = Math.max(maxi, point);
            }
        }
        return maxi;
    }
}

import java.util.*;

public class Solution {
    private static int timer = 1;

    public static ArrayList<Integer> articulationPoints(int V, ArrayList<ArrayList<Integer>> adj) {
        int[] tin = new int[V], low = new int[V];
        boolean[] vis = new boolean[V];
        int[] mark = new int[V];
        timer = 1;
        for (int i = 0; i < V; i++) if (!vis[i]) dfs(i, -1, vis, tin, low, mark, adj);
        ArrayList<Integer> ans = new ArrayList<>();
        for (int i = 0; i < V; i++) if (mark[i] == 1) ans.add(i);
        if (ans.isEmpty()) ans.add(-1);
        return ans;
    }

    private static void dfs(int node, int parent, boolean[] vis, int[] tin, int[] low, int[] mark, ArrayList<ArrayList<Integer>> adj) {
        vis[node] = true;
        tin[node] = low[node] = timer++;
        int child = 0;
        for (int it : adj.get(node)) {
            if (it == parent) continue;
            if (!vis[it]) {
                dfs(it, node, vis, tin, low, mark, adj);
                low[node] = Math.min(low[node], low[it]);
                if (low[it] >= tin[node] && parent != -1) mark[node] = 1;
                child++;
            } else {
                low[node] = Math.min(low[node], tin[it]);
            }
        }
        if (child > 1 && parent == -1) mark[node] = 1;
    }
}

public class Solution {
    // Memoization (Top-down)
    public static int fibMemo(int n, int[] dp) {
        if (n <= 1) return n;
        if (dp[n] != -1) return dp[n];
        return dp[n] = fibMemo(n - 1, dp) + fibMemo(n - 2, dp);
    }
}

public class Solution {
    // Tabulation with Space Optimization (Bottom-up)
    public static int fib(int n) {
        if (n <= 1) return n;
        int prev2 = 0, prev = 1;
        for (int i = 2; i <= n; i++) {
            int cur = prev + prev2;
            prev2 = prev;
            prev = cur;
        }
        return prev;
    }
}

