        if (i == j) return 1;
        if (i > j) return 0;
        if (s.charAt(i) == s.charAt(j)) return 2 + solve(i + 1, j - 1, s);
        return Math.max(solve(i + 1, j, s), solve(i, j - 1, s));
    }
}

