public class Solution {
    static class Node {
        Node[] links = new Node[26];
        boolean flag = false;
    }

    static class Trie {
        Node root = new Node();

        void insert(String word) {
            Node node = root;
            for (char c : word.toCharArray()) {
                int idx = c - 'a';
                if (node.links[idx] == null) node.links[idx] = new Node();
                node = node.links[idx];
            }
            node.flag = true;
        }

        boolean checkIfAllPrefixExists(String word) {
            Node node = root;
            for (char c : word.toCharArray()) {
                int idx = c - 'a';
                if (node.links[idx] != null) {
                    node = node.links[idx];
                    if (!node.flag) return false;
                } else return false;
            }
            return true;
        }
    }

    public static String completeString(int n, String[] a) {
        Trie trie = new Trie();
        for (String word : a) trie.insert(word);
        String longest = "";
        for (String word : a) {
            if (trie.checkIfAllPrefixExists(word)) {
                if (word.length() > longest.length() || (word.length() == longest.length() && word.compareTo(longest) < 0)) {
                    longest = word;
                }
            }
        }
        return longest.isEmpty() ? "None" : longest;
    }
}

