        for (int i = 0; i < n; i++) {
            Node node = root;
            for (int j = i; j < n; j++) {
                int idx = s.charAt(j) - 'a';
                if (node.links[idx] == null) {
                    node.links[idx] = new Node();
                    count++;
                }
                node = node.links[idx];
            }
        }
        return count + 1;
    }
}

