public class Solution {
    static class Node { Node[] links = new Node[2]; }
    static class Trie {
        Node root = new Node();
        void insert(int num) {
            Node node = root;
            for (int i = 31; i >= 0; i--) {
                int bit = (num >> i) & 1;
                if (node.links[bit] == null) node.links[bit] = new Node();
                node = node.links[bit];
            }
        }
        int getMax(int num) {
            Node node = root;
            if (node.links[0] == null && node.links[1] == null) return -1;
            int maxNum = 0;
            for (int i = 31; i >= 0; i--) {
                int bit = (num >> i) & 1;
                if (node.links[1 - bit] != null) {
                    maxNum |= (1 << i);
                    node = node.links[1 - bit];
                } else {
                    node = node.links[bit];
                }
            }
            return maxNum;
        }
    }

    public static int[] maximizeXor(int[] nums, int[][] queries) {
        Arrays.sort(nums);
        int q = queries.length;
        int[][] offlineQueries = new int[q][3];
        for (int i = 0; i < q; i++) {
            offlineQueries[i][0] = queries[i][0];
            offlineQueries[i][1] = queries[i][1];
            offlineQueries[i][2] = i;
        }
        Arrays.sort(offlineQueries, Comparator.comparingInt(a -> a[1]));
        int[] ans = new int[q];
        Trie trie = new Trie();
        int idx = 0, n = nums.length;
        for (int i = 0; i < q; i++) {
            int x = offlineQueries[i][0], m = offlineQueries[i][1], queryIdx = offlineQueries[i][2];
            while (idx < n && nums[idx] <= m) {
                trie.insert(nums[idx++]);
            }
            ans[queryIdx] = trie.getMax(x);
        }
        return ans;
    }
}

