public class Solution {
    public static long computeHash(String s) {
        // Polynomial rolling hash baseline
        long hash = 0, p = 31, m = 1_000_000_007L;
        long p_pow = 1;
        for (char c : s.toCharArray()) {
            hash = (hash + (c - 'a' + 1) * p_pow) % m;
            p_pow = (p_pow * p) % m;
        }
        return hash;
    }
