public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        // Input format:
        // First line: N (number of people)
        // Next N lines: N space-separated 0s and 1s (adjacency matrix)
        // M[i][j] == 1 means person i knows person j
        if (!sc.hasNextInt()) {
            System.out.println("Please provide N followed by the N x N matrix.");
            return;
        }

        int n = sc.nextInt();
        int[][] M = new int[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                M[i][j] = sc.nextInt();
            }
        }

        int celeb = findCelebrity(M, n);
        System.out.println(celeb);
    }

    public static int findCelebrity(int[][] M, int n) {
        int left = 0;
        int right = n - 1;

        // Step 1: Eliminate non-celebrities using two pointers
        while (left < right) {
            if (M[left][right] == 1) {
                // left knows right -> left cannot be a celebrity
                left++;
            } else {
                // left does not know right -> right cannot be a celebrity
                right--;
            }
        }

        // 'left' is now the only potential candidate
        int candidate = left;

        // Step 2: Verify the candidate
        for (int i = 0; i < n; i++) {
            if (i != candidate) {
                // Candidate must not know anyone, and everyone must know the candidate
                if (M[candidate][i] == 1 || M[i][candidate] == 0) {
                    return -1; // No celebrity exists
                }
            }
        }

        return candidate;
    }
}

